34	// success; on failure prints an error tagged with `ctx` and returns "". The
35	// existence check is here, at the shared resolver, so a missing path fails
36	// with a clear "ELF not found" instead of being handed to the engine (e.g.
37	// qemu's cryptic "Unable to find the RISC-V BIOS").
38	std::string abs_elf(const std::string& path, const std::string& ctx) {
39	  std::error_code ec;
40	  fs::path abs = fs::absolute(path, ec);
41	  if (ec) {
42	    std::fprintf(stderr, "andesim run %s: cannot resolve ELF '%s'\n",
43	                 ctx.c_str(), path.c_str());
44	    return "";
45	  }
46	  if (!fs::is_regular_file(abs, ec)) {
47	    std::fprintf(stderr, "andesim run %s: ELF not found: %s\n", ctx.c_str(),
48	                 path.c_str());
49	    return "";
50	  }
51	  return abs.string();
52	}
