54	// Validate the lone-ELF positional shape the standalone models require: print
55	// the diagnostic and return 2 on a violation, else 0. `model` labels the error.
56	int check_one_elf(const Cli& cli, const char* model) {
57	  if (cli.positional.empty()) {
58	    std::fprintf(stderr,
59	                 "andesim run --mode %s: missing ELF (the workload to run; "
60	                 "e.g. a tests/fixtures/<name>.elf)\n",
61	                 model);
62	    return 2;
63	  }
64	  if (cli.positional.size() > 1) {
65	    std::fprintf(stderr,
66	                 "andesim run --mode %s: unexpected argument '%s' "
67	                 "(engine args go after --)\n",
68	                 model, cli.positional[1].c_str());
69	    return 2;
70	  }
71	  return 0;
72	}
