74	// Print the dry-run preview: the exact command(s) andesim WOULD spawn, each
75	// shell-quoted and labeled, executing nothing. Shared by every --mode so the
76	// preview format is identical; `labels[i]` annotates `argvs[i]` (e.g.
77	// "fast-leg [qemu64]", "standalone [qemu64]"). Always returns 0 -- a dry run
78	// reports the plan, it does not run it.
79	int print_dry_run(const std::vector<std::vector<std::string>>& argvs,
80	                  const std::vector<std::string>& labels) {
81	  std::printf("[andesim] dry-run: %zu command(s), not executed\n", argvs.size());
82	  for (size_t i = 0; i < argvs.size(); ++i) {
83	    std::printf("# command %zu/%zu: %s\n", i + 1, argvs.size(),
84	                labels[i].c_str());
85	    std::printf("%s\n", render_argv(argvs[i]).c_str());
86	  }
87	  return 0;
88	}
