90	// The standalone spine: take a single ELF, then run the resolved engine
91	// standalone with the post-`--` args appended verbatim (exec_passthrough --
92	// inherit stdio, no timeout, propagate the exit code, so an interactive
93	// gdbstub / monitor / semihosting console works unchanged). The per-model
94	// engine + selection are resolved by the caller; `model` here only labels
95	// the positional diagnostics.
96	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
97	                   const char* model, const std::vector<std::string>& extra = {}) {
98	  if (int rc = check_one_elf(cli, model)) return rc;
99	  // QEMU's -bios flag searches its data directory for relative paths rather
100	  // than the CWD; resolve to absolute so the engine finds the ELF.
101	  const std::string elf = abs_elf(cli.positional[0], "--mode " + std::string(model));
102	  if (elf.empty()) return 2;
103	  // `extra` (framework flags, e.g. fast's -m) precedes the post-`--` args, so a
104	  // user's own flag after `--` wins.
105	  std::vector<std::string> args = extra;
106	  args.insert(args.end(), cli.passthrough.begin(), cli.passthrough.end());
107	  std::string err;
108	  const std::vector<std::string> argv =
109	      passthrough_argv(eng, "standalone", elf, args, err);
110	  if (!err.empty()) {
111	    std::fprintf(stderr, "andesim run: %s\n", err.c_str());
112	    return 2;
113	  }
114	  // --dry-run: print the exact engine command and stop, spawning nothing -- the
115	  // full qemu/vsim command (incl. -bios <elf> and any post-`--`).
116	  if (cli.dry_run)
117	    return print_dry_run({argv}, {std::string("standalone [") + eng.id + "]"});
118	  return exec_passthrough(argv);
119	}
