144	// `run --mode cycle`: one cycle-accurate engine alone, from reset (no QEMU,
145	// no --resume-from-qemu), transparent passthrough -- cycles surface in the
146	// engine's own output. Unlike fast, this must discover the vsim build(s) to
147	// resolve the engine (explicit --engine, else the sole one).
148	int run_accurate(const Cli& cli) {
149	  // Reject a missing/extra ELF before discovery so a CLI typo does not spawn a
150	  // --describe subprocess per vsim build only to fail on the argument.
151	  if (int rc = check_one_elf(cli, "cycle")) return rc;
152	  // --mem-size is validated but has nothing to size: the cycle engine always
153	  // models its full DRAM window. Say so instead of silently ignoring it.
154	  if (!cli.mem_size.empty()) {
155	    std::string se;
156	    if (parse_size(cli.mem_size, se); !se.empty()) {
157	      std::fprintf(stderr, "andesim run --mode cycle: --mem-size: %s\n",
158	                   se.c_str());
159	      return 2;
160	    }
161	    std::fprintf(stderr,
162	                 "[andesim] --mem-size: the cycle engine models its full "
163	                 "DRAM window; nothing to size\n");
164	  }
165	  Discovery disc = discover_engines();
166	  std::string err;
167	  const EngineDescriptor* eng =
168	      resolve_accurate_engine(disc.engines, cli.engine, err);
169	  if (!eng) {
170	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", err.c_str());
171	    // Surface why an expected engine may be absent (failed --describe, etc.).
172	    for (const std::string& w : disc.warnings)
173	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
174	    return 2;
175	  }
176	  return run_standalone(cli, *eng, "cycle");
177	}
