179	// `run --mode hybrid`: orchestrate a QEMU1 fast-forward -> vsim measure+drain
180	// handoff (no QEMU2). The trigger (marker|pc) delimits the ROI; the cycle
181	// figure is the vsim mcycle minus QEMU1's drained mcycle. Replaces the Python
182	// driver's tests/e2e.sh delegation with a single window-cycle line.
183	int run_hybrid(const Cli& cli) {
184	  // Single diagnostic sink for the early-validation returns: prefix + exit 2.
185	  auto fail = [](const std::string& msg) {
186	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", msg.c_str());
187	    return 2;
188	  };
189	
190	  if (int rc = check_one_elf(cli, "hybrid")) return rc;
191	
192	  // Resolve to an absolute, existing ELF through the shared resolver -- the same
193	  // check and "ELF not found" message fast/cycle get (abs_elf already printed on
194	  // failure). pc-trigger resolution below then reads the ELF's .symtab.
195	  const std::string elf_path = abs_elf(cli.positional[0], "--mode hybrid");
196	  if (elf_path.empty()) return 2;
197	  const fs::path elf{elf_path};  // for .stem() in the banner / PASS lines
198	
199	  // Validate everything cheap BEFORE the expensive engine discovery, so a CLI
200	  // mistake fails fast without spawning a --describe per Verilator build.
201	  std::string err;
202	  const Trigger trig = hybrid_trigger(cli, elf_path, err);
203	  if (!err.empty()) return fail(err);
204	
205	  std::vector<std::string> vsim_extras = vsim_extra_args(cli, trig.kind, err);
206	  if (!err.empty()) return fail(err);
207	
208	  long long mem = 128LL * 1024 * 1024;  // shared mmap; --mem-size overrides
209	  if (!cli.mem_size.empty()) {
210	    std::string se;
211	    mem = parse_size(cli.mem_size, se);
212	    if (!se.empty()) return fail("--mem-size: " + se);
213	    // Early cap: QEMU's AE350 DRAM window is 2 GiB and the mmap backend doubles
214	    // as guest RAM here. Failing now beats allocating a huge mmap file first and
215	    // letting QEMU die late.
216	    if (mem > 2LL * 1024 * 1024 * 1024)
217	      return fail("--mem-size " + cli.mem_size +
218	                  " exceeds the AE350 DRAM window (2G)");
219	  }
220	
221	  // qemu is the built-in fast leg; resolve the accurate (vsim) leg by --engine
222	  // or the sole cycle-accurate engine (reusing the F8 selector).
223	  Discovery disc = discover_engines();
224	  const EngineDescriptor* acc =
225	      resolve_accurate_engine(disc.engines, cli.engine, err);
226	  if (!acc) {
227	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", err.c_str());
228	    for (const std::string& w : disc.warnings)
229	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
230	    return 2;
231	  }
232	
233	  // ISA sync: both legs must agree on the base ISA width (rv32 engines
234	  // cannot share architectural state with the rv64 fast leg).
235	  if (std::string hw = hybrid_hw_check(*acc); !hw.empty()) return fail(hw);
236	
237	  Plan plan;
238	  plan.elf = elf_path;
239	  plan.mem_size = mem;
240	  Step qemu_step{kQemuId, "fast-leg", trig};
241	  Step vsim_step{acc->id, "accurate-leg", trig};
242	  vsim_step.extra_args = std::move(vsim_extras);  // kanata, validated
243	  plan.steps = {qemu_step, vsim_step};
244	
245	  // Banner to stderr so the window-cycle result stands alone on stdout.
246	  // vlen is the synced value the fast leg inherits from the engine.
247	  std::fprintf(stderr,
248	               "[andesim] model=hybrid engine=%s vlen=%ld trigger=%s fixture=%s\n",
249	               acc->id.c_str(), synced_vlen(acc->vlen), trig.kind.c_str(),
250	               elf.stem().string().c_str());
251	
252	  PlanOptions opts;
253	  opts.dry_run = cli.dry_run;
254	  const PlanResult r = run_plan(plan, disc.engines, opts);
255	  if (!r.ok()) {
256	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", r.error.c_str());
257	    return 1;
258	  }
259	  // --dry-run: print the exact per-leg commands run_plan assembled -- the QEMU
260	  // fast leg (incl. the staged -readconfig from the engine's --print-qemu-config)
261	  // then the vsim accurate leg -- and stop. Nothing was spawned.
262	  if (cli.dry_run) {
263	    std::vector<std::string> labels;
264	    labels.reserve(plan.steps.size());
265	    for (const Step& s : plan.steps)
266	      labels.push_back(s.role + " [" + s.engine_id + "]");
267	    return print_dry_run(r.argvs, labels);
268	  }
269	  // phases[0] = QEMU1 drain, [1] = vsim drain; the kernel/window figure is the
270	  // vsim mcycle delta.
271	  const unsigned long long q_mc = r.phases[0].mcycle;
272	  const unsigned long long v_mc = r.phases[1].mcycle;
273	  std::printf("[%s window_cycles] %llu  (vsim mcycle=%llu - qemu mcycle=%llu)\n",
274	              trig.kind.c_str(), v_mc - q_mc, v_mc, q_mc);
275	  std::printf("PASS: --mode hybrid --trigger %s (%s)\n", trig.kind.c_str(),
276	              elf.stem().string().c_str());
277	  return 0;
278	}
