282	int cmd_run(const Cli& cli) {
283	  if (cli.model.empty()) {
284	    std::fprintf(stderr,
285	                 "andesim run: --mode fast|cycle|hybrid is required "
286	                 "(pick the composition; see 'andesim run --help')\n");
287	    return 2;
288	  }
289	  if (!find_model(cli.model)) {
290	    std::fprintf(stderr,
291	                 "andesim run: unknown model '%s' (want fast|cycle|hybrid)\n",
292	                 cli.model.c_str());
293	    return 2;
294	  }
295	  // Post-`--` args are forwarded verbatim to the engine -- but hybrid has TWO
296	  // legs (a QEMU fast-forward + a vsim measure leg) whose command lines the
297	  // handoff builds itself, so there is no single "the engine" to forward to.
298	  // Reject rather than silently drop (the old behavior) or guess a leg. vsim
299	  // options have dedicated flags (--kanata/--objdump); fast/cycle still forward.
300	  if (!cli.passthrough.empty() && cli.model == "hybrid") {
301	    std::fprintf(stderr,
302	                 "andesim run: --mode hybrid takes no `-- <args>` (the handoff "
303	                 "builds both legs' command lines; use --kanata/--objdump for "
304	                 "vsim options, or --mode fast|cycle to forward to one engine)\n");
305	    return 2;
306	  }
307	  // --trigger / --pc-start / --pc-end delimit the hybrid ROI window. --trigger
308	  // is hybrid-only; --pc-start/--pc-end belong to --trigger pc specifically. Any
309	  // other mode/trigger would SILENTLY drop them and hand back a figure for the
310	  // wrong window (fast/cycle: the whole program; hybrid+marker: the marker
311	  // window), so reject instead of measuring something the user did not ask for.
312	  if (!cli.trigger.empty() && cli.model != "hybrid") {
313	    std::fprintf(stderr,
314	                 "andesim run: --trigger applies only to --mode hybrid "
315	                 "(the ROI delimiter); fast/cycle run the whole program\n");
316	    return 2;
317	  }
318	  if (!cli.pc_end.empty() && cli.trigger != "pc") {
319	    std::fprintf(stderr,
320	                 "andesim run: --pc-end applies only to --mode hybrid "
321	                 "--trigger pc\n");
322	    return 2;
323	  }
324	  if (!cli.pc_start.empty() && cli.trigger != "pc") {
325	    std::fprintf(stderr,
326	                 "andesim run: --pc-start applies only to --mode hybrid "
327	                 "--trigger pc\n");
328	    return 2;
329	  }
330	  if (cli.model == "fast") return run_fast(cli);
331	  if (cli.model == "cycle") return run_accurate(cli);
332	  return run_hybrid(cli);  // model validated above; only hybrid remains
333	}
